(80, 1, 'create', 'access_points', 14, NULL, '{\"access_point_id\":14,\"name\":\"Gubat National High School\",\"category\":\"facility\",\"sub_type\":\"school\",\"latitude\":\"12.9162747\",\"longitude\":\"124.1202210\",\"address\":\"Mandirigma, Gubat, Sorsogon\",\"description\":\"Gubat National High School is a public secondary school located in Gubat, Sorsogon, Philippines. It is one of the primary government-funded high schools in the municipality of Gubat, serving students from the town proper and surrounding barangays. The school operates under the Department of Education (DepEd) and offers the standard K-12 curriculum, including Junior High School (Grades 7\\u201310) and Senior High School (Grades 11\\u201312) programs.\",\"photo_url\":\"assets\\/uploads\\/photos\\/489460c28372d0108b2755c2.jpg\",\"status\":\"active\",\"created_by\":1,\"updated_by\":1,\"created_at\":\"2026-03-12 00:13:25\",\"updated_at\":\"2026-03-12 00:13:25\",\"created_by_name\":\"System Administrator\",\"updated_by_name\":\"System Administrator\"}', '2026-03-11 16:13:25'),
(81, 1, 'create', 'access_points', 15, NULL, '{\"access_point_id\":15,\"name\":\"PAMANA Terminal\",\"category\":\"transport\",\"sub_type\":\"major_terminal\",\"latitude\":\"12.9194627\",\"longitude\":\"124.1221353\",\"address\":\"Poblacion, Gubat, Sorsogon\",\"description\":\"Pamana Terminal is a public transport terminal located in Gubat, Sorsogon that serves as a key transit hub in the eastern coastal area of the province. It facilitates the movement of passengers traveling between Gubat and other municipalities via jeepney and tricycle routes, connecting commuters to Sorsogon City and nearby coastal barangays. The terminal supports the daily transport needs of local residents, market-goers, students, and workers, and plays an important role in the local economy by providing an organized departure and arrival point for public utility vehicles operating along the Gubat route corridor.\",\"photo_url\":\"assets\\/uploads\\/photos\\/897e3bfaf3adce59c552d76c.jpg\",\"status\":\"active\",\"created_by\":1,\"updated_by\":1,\"created_at\":\"2026-03-12 00:18:34\",\"updated_at\":\"2026-03-12 00:18:34\",\"created_by_name\":\"System Administrator\",\"updated_by_name\":\"System Administrator\"}', '2026-03-11 16:18:34'),
