(84, 1, 'create', 'disaster_zones', 3, NULL, '{\"zone_id\":3,\"zone_name\":\"Bacon Flood\",\"zone_type\":\"flood\",\"severity\":\"high\",\"latitude\":\"13.0405241\",\"longitude\":\"124.0387579\",\"radius_meters\":1043,\"description\":\"Bacon are now are classified as a high-risk flood area. Flooding typically occurs during prolonged rainfall or typhoon events when nearby waterways overflow. The area may become impassable to vehicles and pedestrians. Authorities should issue traffic advisories and redirect vehicles to safer routes. Residents and travelers are advised to remain alert for flood warnings.\",\"photo_url\":\"assets\\/uploads\\/photos\\/963aa830caf2186d0e1cf21b.jpg\",\"status\":\"active\",\"created_by\":1,\"updated_by\":1,\"reported_at\":\"2026-03-12 00:50:21\",\"resolved_at\":null,\"created_by_name\":\"System Administrator\",\"updated_by_name\":\"System Administrator\"}', '2026-03-11 16:50:21'),
(85, 1, 'create', 'access_points', 17, NULL, '{\"access_point_id\":17,\"name\":\"GSAC General Hospital\",\"category\":\"emergency\",\"sub_type\":\"hospital\",\"latitude\":\"12.9795677\",\"longitude\":\"124.0158559\",\"address\":\"Barangay Road, Balogo, Sorsogon City\",\"description\":\"City General Hospital is a public healthcare facility providing emergency and general medical services to residents and travelers. The hospital operates 24 hours a day and serves as a primary medical response center during accidents, disasters, and health emergencies. It is equipped with emergency rooms, inpatient wards, and basic diagnostic facilities.\",\"photo_url\":\"assets\\/uploads\\/photos\\/02867269f93d6d7aefabb8db.jpg\",\"status\":\"active\",\"created_by\":1,\"updated_by\":1,\"created_at\":\"2026-03-12 00:54:35\",\"updated_at\":\"2026-03-12 00:54:35\",\"created_by_name\":\"System Administrator\",\"updated_by_name\":\"System Administrator\"}', '2026-03-11 16:54:35'),
